using static StrataLint.Scribe.DefinitionDsl;
using StrataLint.Scribe;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class ReturnCycleWordsDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/Hyperideal/ReturnCycleWords.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "For the original paired-edge relation, the six edge slots split into two families and every actual edge chain is exactly an orbit of the corresponding return word.",
        H("Noncommutative edge return orbits"),
        Blocks(
            Def("edgeClass", "Original edge equivalence closure",
                "edgeClass is the equivalence closure of the original edgeRel(pairing u v); all later orbit statements refer to this unchanged relation."),
            Def("family", "Edge family",
                "family is false on slots 0, 3 and 5 and true on slots 1, 2 and 4. It records the low/high edge family without identifying the two families."),
            Def("baseEdge", "Representative edge slot",
                "The low family uses representative slot 0 and the high family representative slot 1."),
            Def("normalizeEdge", "Normalized edge coordinate",
                "The six slot multipliers are [1, 1, v*u, u squared, u, u], in slot order 0 through 5. The normalized coordinate is in representative slot 0 for the low family and slot 1 for the high family."),
            Def("returnWord", "Edge return word",
                "The low return word is v inverse times u squared and the high return word is v squared times u."),
            Def("returnGroup", "Return subgroup",
                "returnGroup is the subgroup closure of the selected return word, so inverse and product powers remain inside the same actual family."),
            Paragraph(Text(
                "For the low return word ell = v inverse times u squared, centrality has a concrete consequence when u and v generate the entire group. Assume the subgroup closure of {u,v} equals the whole group and ell belongs to its center. Centrality gives Commute(u,ell), while the group identity v = u squared times ell inverse expresses v in terms of u and a central element.")),
            Paragraph(Text(
                "The existing inverse, power and product rules for Commute therefore give Commute(u,v). Every pair in {u,v} commutes; Mathlib's Subgroup.isMulCommutative_closure then proves that their generated subgroup is commutative. The generation assumption identifies this subgroup with the whole group. Thus a group generated by these two elements is commutative whenever its low return word is central.")),
            Paragraph(Text(
                "Consequently, in a noncommutative group generated by the marked pair u,v, the low return word cannot be central. The generation hypothesis concerns the same marked pair used in the edge relation. A concrete matrix group still requires identification of the marked matrices, proof of their generation, and the actual return orders before this application supplies information about its edge degrees.")),
            Paragraph(Text(
                "Assume now that Omega is finite, with the same opposite-group action and marked elements u,v. For a sheet x and either edge family, let n be the minimal period of x under its return word. This period is positive. The existing actual-edge orbit characterization identifies the full fiber of the original quotient map P over the representative occurrence with three copies of the return orbit, so the fiber contains exactly three times n actual occurrences.")),
            Paragraph(Text(
                "The bijection retains the actual local slot: low slots are 0, 3 and 5, and high slots are 1, 2 and 4. Each of these three slot fibers has exactly n elements. The middle slot is 5 in the low family and 2 in the high family; its fiber therefore has n elements, while the two other slots together have twice n elements. These are occurrence counts in the unchanged paired-edge quotient, with no identification of repeated local incidences.")),
            Paragraph(Text(
                "Concretely, a period index selects an iterate of the normalized sheet coordinate, and the chosen slot uses the inverse of its original normalization multiplier to recover the actual sheet. Normalization and uniqueness below the minimal period make this assignment a bijection. Finiteness of Omega suffices; the action need not be free, faithful or transitive. Applying these counts to a concrete geometric model still requires identifying its marked action and return periods; the occurrence calculation alone does not establish endpoint orientation or link topology.")),
            Describe.Lean(
                DescribeId.Create("noncommutative-edge-actual-orbit-iff"),
                DeclarationHandle.Create(Prefix + "actual_edge_orbit_iff"),
                H("Actual edge equivalence is exactly a return orbit"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text(
                    "For every group G, every type Omega with the opposite-group action, all u,v in G and occurrences a,b in Omega times Fin(6), the equivalence closure of the original edgeRel(pairing u v) relates a and b exactly when they have the same low/high family and some element of the corresponding returnGroup sends the normalized coordinate of a to that of b. The forward proof checks every actual face-slot generator and propagates the invariant through reflexive, symmetric and transitive chains. The reverse proof expands a subgroup word into actual three-step cycles and connects every occurrence to its normalized representative. No finiteness, faithfulness, transitivity or freeness assumption is used. This characterizes the edge relation only; it does not assert endpoint orientation, link topology, metric geometry, Euler characteristic or a polygon-manifold realization."))),
                DescribeRole.Theorem))));

    private static DocumentBlock.Describe Def(string name, string heading, string text) =>
        Describe.Lean(DescribeId.Create("noncommutative-edge-" + name.ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(heading),
            StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(text))), DescribeRole.Definition);
}
